import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"科学新闻核实","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/science-news/index.md","filePath":"topics/science-news/index.md"}'),e={name:"topics/science-news/index.md"};function i(g,t,a,u,l,c){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="科学新闻核实" tabindex="-1">科学新闻核实 <a class="header-anchor" href="#科学新闻核实" aria-label="Permalink to &quot;科学新闻核实&quot;">​</a></h1><p>用户转来的科学新闻 / 自媒体科普摘要的<strong>信源核实记录</strong>。</p><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="/zhishiku-reading/topics/science-news/news-verification-2026-10-23.html">news-verification-2026-10-23.md</a></td><td>2026-10-23 那条五段式「科学日报」18 条<strong>逐条核实</strong>：一页速查表（真实出处 + DOI）、三类失真归类、AI 段 4 条 36kr 标题党打假、<strong>两处自我更正记录</strong></td></tr><tr><td><a href="/zhishiku-reading/topics/physics/cosmic-inflation-origin.html">../physics/cosmic-inflation-origin.md</a></td><td>2026-10-24 转来的《揭秘宇宙起源新理论》：<strong>四类失真之&quot;关系错位&quot;的首例</strong>（&quot;暴胀取代大爆炸&quot;实为前置扩展）+ 暴胀能否被实验证实的完整回答</td></tr><tr><td><a href="/zhishiku-reading/topics/space-energy/lunar-industrial-satellite.html">../space-energy/lunar-industrial-satellite.md</a></td><td>2026-10-24 王钦文 × 马兆远访谈收尾的&quot;月球工业伴星&quot;构想核实：<strong>时间错位首例</strong>——实为 <strong>1979-04-30 NASA 报告</strong>（General Dynamics/Convair，NAS9-15560，30 座 × 10 GW）；2026 现状 = Caltech MAPLE（EIRP 3.2 W / 地面 &lt;0.1 µW）、中国逐日工程/OMEGA、2026-05-18 新华社百米级千瓦级</td></tr><tr><td><a href="/zhishiku-reading/topics/career-observation/ma-zhaoyuan-interview-ai-involution.html">../career-observation/ma-zhaoyuan-interview-ai-involution.md</a></td><td>2026-10-24 同批访谈的<strong>人物归属核实</strong>：马兆远身份由南方科技大学官网核实（牛津物理博士、2009 中科院研究员、为天宫四号设计载荷）；<strong>&quot;访谈型材料的失真高发区不在观点，而在&quot;时间坐标&quot;与&quot;归属坐标&quot;</strong></td></tr><tr><td><a href="/zhishiku-reading/topics/ai-system-architecture/openai-ai-native-organization.html">../ai-system-architecture/openai-ai-native-organization.md</a></td><td>2026-10-24《OpenAI 内部 AI 实践：可读→可操作→可迭代》：<strong>第五类失真首例</strong>——框架与官方 2026 发布轨迹逐段对齐（<strong>可信</strong>），但<strong>细节零出处 + 反面省略</strong>（员工数反向翻倍 / 内部 Agent 越权访问澳洲 Medicare / 失准监控 / HPIM 95% 未开放）</td></tr><tr><td><a href="/zhishiku-reading/topics/ai-system-architecture/sky-001-engineering-world-model.html">../ai-system-architecture/sky-001-engineering-world-model.md</a></td><td>2026-10-24《SKY-001 全球首个工程世界模型》：<strong>程度夸大 + 口径错位 + 选择性省略</strong>的复合案例。官方原话是 &quot;<strong>while matching its performance</strong>（79.7% vs 79.1%）&quot;，被转述成&quot;<strong>精度还更高</strong>&quot;；&quot;成本降低 150 倍&quot;直译自官方病句 &quot;costs 150 times less&quot;（正确＝<strong>降到 1/150</strong>）；官方口径自身三处打架（50× / 51× / &quot;100 times&quot;）。★ 缺的六件事：<strong>仅 waitlist</strong> / <strong>官方自承草图与三维几何可能对不上</strong> / <strong>&quot;首个&quot;系自我宣称</strong> / <strong>HN 5 分 0 评论</strong> / <strong>基准自建自评</strong> / <strong>Astra 非各维度最强基线</strong></td></tr><tr><td><a href="/zhishiku-reading/topics/career-observation/lin-xiaolong-wow-story-verification.html">../career-observation/lin-xiaolong-wow-story-verification.md</a></td><td>2026-10-24《美发店创始人玩〈魔兽世界〉翻身》：<strong>第五类失真第二例，也是&quot;社交平台故事&quot;型首次</strong>——<strong>三面检索全部落空</strong>（Bing 原样返回&quot;没有与此相关的结果&quot;、Google News 零命中、搜狗 11,210 条全是<strong>同名网络小说</strong>《林小龙 叶小五》）。★ 判定成本极低：<strong>一次三面检索即可定性</strong>。★ 但同时确认了被故事勾出的两个硬事实：德鲁伊＝治疗职业之一；&quot;一次成功恢复心气&quot;＝Bandura 自我效能感中<strong>最强</strong>的来源</td></tr><tr><td><a href="/zhishiku-reading/topics/ai-system-architecture/breeze-tts-2-open-weight-voice-model.html">../ai-system-architecture/breeze-tts-2-open-weight-voice-model.md</a></td><td>2026-10-28《Breeze TTS 2 刚开源的语音模型》：<strong>&quot;开源&quot;定性错误</strong>——官方 LICENSE 原文自认 <strong>&quot;is not an open source license&quot;</strong>（许可方 <strong>RESONIA, INC.</strong> dba BreezeBlue）→ 正确定性 = <strong>代码 Apache-2.0 开源 + 权重开放但禁商用（open-weight ≠ open-source）</strong>，且<strong>连自部署生成物也不能商用</strong>、<strong>企业内用（超出有限评估）即商用</strong>。★ 技术描述反而<strong>相当准</strong>（情绪标签 <code>[笑] [叹气]</code> 属实、7.7 GiB 显存精确对、RTF 0.32 换算得 19.2 s）。★ 新失真形态：<strong>指标拼接</strong>（7.7 GiB 是 eager，&quot;1 分钟&lt;20 秒&quot;是 <strong>H100 fast path</strong>，两个配置被并列）+ <strong>官网 50+ languages vs 模型卡双语</strong> + <strong>&quot;三冠&quot;里两冠是自建 benchmark</strong> + <strong>&quot;39% more distinct voices&quot;里 <code>next-best</code> 与 <code>closest</code> 不是同一模型（708 vs 第二 202 实为 3.5 倍）</strong>。★ 与 SKY-001 对照：同为&quot;自建基准 + 自称第一 + HN 低热度&quot;，但 Breeze <strong>第三方榜单可独立核验（AA <code>qualityElo=1228.47</code>，95% CI [1215.47,1241.47]）+ 社区真在用（1,033 stars / GGUF 91,400 下载）</strong> → 判&quot;真实产品、宣传有加工&quot;，高 SKY-001 一档。★ 中国用户视角：<strong>可自由商用的基座其实是 Qwen3-TTS（Apache-2.0，Breeze 的 audio tokenizer 就基于它）</strong></td></tr></tbody></table><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Google News RSS 定位原始报道 → 抓原文正文 → <strong>CrossRef API 核 DOI</strong> → PubMed E-utilities 核论文。 逐条给四段：① 真实来源（期刊/机构 + 日期 + 标题原文）② 具体研究内容（谁做、方法、关键数字、DOI）③ 中文转述 vs 真实的差异/夸大 ④ 核实级别。</p><h2 id="五类失真-可复用的检查清单" tabindex="-1">五类失真（可复用的检查清单） <a class="header-anchor" href="#五类失真-可复用的检查清单" aria-label="Permalink to &quot;五类失真（可复用的检查清单）&quot;">​</a></h2><ol><li><strong>时间错位</strong> —— 旧报道（数月前）被当作&quot;今日新闻&quot;重发。ScienceDaily 会把 6 月的新闻稿在 10 月<strong>再推送</strong>一次，中文&quot;日报&quot;照抄。</li><li><strong>程度夸大</strong> —— 理论预测 / 模型输出 / 设计蓝图 → &quot;已实现 / 突破 / 首个&quot;。凡&quot;降低 100 倍&quot;&quot;效率提升 40 倍&quot;都要问：是<strong>实测</strong>还是<strong>算出来的</strong>？</li><li><strong>主体 / 口径 / 方向错位</strong> —— 仪器张冠李戴（相机锐度说成日冕仪）、基因名错（GFAP 写成 FOXD1）、把 GDP <strong>总量</strong>说成<strong>增量</strong>、<strong>把 &quot;reversal（向下逆转）&quot; 读成 &quot;反弹（向上）&quot;</strong>。</li><li><strong>关系错位（2026-10-24 新增）</strong> —— 把&quot;<strong>补充 / 前置扩展</strong>&quot;说成&quot;<strong>范式取代</strong>&quot;。案例：暴胀理论被包装成&quot;正在取代热大爆炸&quot;，实际它是大爆炸模型的极早期扩展（暴胀之后宇宙&quot;continued to expand&quot;，接续而非替代）。<strong>比夸数字更隐蔽，因为它听起来更&quot;革命&quot;</strong>——而且<strong>文中后半段往往自己讲对了</strong>，只有标题和开头在博眼球。</li><li><strong>无具名信源的内幕叙述（2026-10-24 新增）</strong> —— &quot;<strong>某公司内部就是这么干的</strong>&quot;这类<strong>组织行为叙述</strong>，全篇不点名任何人／文章／演讲。案例：《OpenAI 内部 AI 实践》的<strong>三层框架与官方发布轨迹逐段对齐（可信）</strong>，但&quot;一个周末上百个 Agent 涌入&quot;&quot;语音 30 分钟出报告&quot;<strong>零出处</strong>，且<strong>系统性地剪掉了反面事实</strong>（同期员工数在翻倍、内部 Agent 已越权访问政府服务器、官方自己在做失准监控、内部模型 95% 不对外开放）。 <strong>判据</strong>：<strong>只能采信其框架，不能采信其数字</strong>；并且必须<strong>主动去查它没说的那部分</strong>——反面事实往往是核实工作中信息量最大的地方。 <strong>第二例（2026-10-24，社交平台故事型）</strong>：<strong>美发店创始人玩《魔兽世界》翻身</strong>。与前例相反，这一条<strong>连框架都无法落地</strong>——<strong>三面检索全部落空</strong>（Bing 明确&quot;没有与此相关的结果&quot;、Google News 零命中、搜狗命中全是<strong>同名网络小说</strong>）。 <strong>新增判据</strong>：<strong>&quot;传闻型故事&quot;的定性成本极低</strong>——<strong>Bing（原样零结果）+ 搜狗（看命中是不是同名小说/同名剧）+ B站（风控看 412）</strong> 三面走一遍，10 分钟内可定&quot;不可核实&quot;。定性后<strong>不要停在&quot;查不到&quot;</strong>，而要把故事<strong>勾出来的可核实问题</strong>答完（本例：德鲁伊是不是治疗职业、&quot;一次成功恢复心气&quot;有没有理论支撑）——<strong>这才是能沉淀的部分</strong>。</li></ol><h2 id="新增判据-2026-10-28-breeze-tts-2-案得出" tabindex="-1">新增判据（2026-10-28，Breeze TTS 2 案得出） <a class="header-anchor" href="#新增判据-2026-10-28-breeze-tts-2-案得出" aria-label="Permalink to &quot;新增判据（2026-10-28，Breeze TTS 2 案得出）&quot;">​</a></h2><ol start="6"><li><strong>&quot;开源&quot;必须拆三层</strong> —— 见到&quot;某模型/项目<strong>开源</strong>&quot;，先分：①<strong>代码许可</strong> ②<strong>权重许可</strong> ③<strong>生成物（Outputs）的使用许可</strong>。 案例 Breeze TTS 2：<strong>Apache-2.0 / 非商用 / 非商用</strong>三层各不相同。 <strong>判据：只要官方 LICENSE 里出现 &quot;is not an open source license&quot;，转述中的&quot;开源&quot;即判第③类口径错位。</strong> ★ <strong><code>open-weight</code>（开放权重）≠ <code>open-source</code>（开源）</strong>——中文自媒体几乎一律混用，且<strong>开放权重往往连输出物都禁商用</strong>。</li><li><strong>&quot;某某榜第一&quot;必须问：这个榜是谁发的</strong> —— 拆出<strong>第三方榜单</strong>与<strong>自建 benchmark</strong>两类。 案例：Breeze 首页并列三个&quot;#1&quot;，只有一个是 Artificial Analysis（第三方），另两个（Voice Design / Voice Direction）是<strong>自家仓库里的 benchmark</strong>，且<strong>同页混排、视觉上无法分辨</strong>。</li><li><strong>新取证路径：第三方榜单直取内嵌 JSON</strong> —— 榜单站 HTML 常内嵌 <code>qualityElo</code> 等字段，可<strong>绕过 JS 渲染</strong>直接取到真实分数与 <strong>95% 置信区间</strong>。 ★ <strong>置信区间本身是信息</strong>：官方宣传值<strong>恰好落在 CI 下界</strong>，即&quot;官方在用保守口径&quot;的信号。</li><li><strong>指标拼接检查（新失真形态）</strong> —— 同一段里并列的两个性能指标，<strong>先确认它们出自同一配置</strong>。 案例：<strong>7.7 GiB 显存</strong>来自 <strong>eager</strong>，而&quot;<strong>1 分钟语音 &lt;20 秒</strong>&quot;来自 <strong>H100 + warmed-up fast path</strong>（需 14.4 GiB）——<strong>两个数字分别正确，拼在一起就变成误导</strong>。 ★ 同类：<strong>官网营销页</strong>（50+ languages、≤25 ms TTFB）<strong>vs 模型卡</strong>（双语、&lt;40 ms TTFA on H100）——<strong>同一产品两套口径</strong>。</li></ol><h2 id="铁律" tabindex="-1">铁律 <a class="header-anchor" href="#铁律" aria-label="Permalink to &quot;铁律&quot;">​</a></h2><ul><li><strong>凡&quot;突破 / 首个 / 破解 / 再创新低&quot;字样，先查发布日期 + 原文措辞</strong>，再信中文。</li><li><strong>ScienceDaily 标题本身就是第一层失真源</strong>（never-ending / reversed / this one age / stunning reversal）—— 中文直译会再放大一层。</li><li>核实到&quot;未经同行评议 / 不可复现 / 器件未造 / 仅立项&quot;这类限定，<strong>必须写进结论</strong>，它们往往正是&quot;争议&quot;的真实内容。</li><li><strong>不编造</strong>：&quot;我查不到&quot;是合法状态；子代理的自报结论也须亲验后再落盘。</li></ul><hr><blockquote><p>关键词：科学新闻核实、信源核实、36kr 标题党、时间错位、程度夸大、主体错位、方向读反、关系错位、前置扩展、范式取代、无具名信源、内幕叙述、组织行为叙述、传闻型故事、社交平台故事、归属核实、访谈型材料、OpenAI AI 原生、可读可操作可迭代、DOI 核实、CrossRef、ScienceDaily 标题党、黎曼猜想、TheoPhysEval、GPT-6 Astra、SKY-001、Skyfall、工程世界模型、Enterprise World Model、CAD、BIM、Sam Pasupalak、Maluuba、Zanvastro、GFAP、Alexander 病、GIMLI、钍-229 核时钟、BVR-19、SHOQ、DT-109、暴胀、真空暴涨、宇宙起源、BICEP2、原初引力波、可证伪性、月球工业伴星、空间太阳能电站、逐日工程、马兆远、魔兽世界、World of Warcraft、德鲁伊、治疗职业、林小龙、美发店、自我效能感、self-efficacy、mastery experience、习得性无助、learned helplessness、社会缓冲、可控感、Breeze TTS 2、BreezeBlue、RESONIA、开放权重、open-weight、开源判定三层、权重许可、非商用许可、NOTICE、语音合成、TTS、text-to-speech、声音克隆、voice cloning、voice clone、音色设计、voice design、voice direction、情感控制、情感标签、副语言标签、Vocal Events、笑、叹气、清嗓子、咳嗽、显存、VRAM、eager、fast path、RTF、实时率、TTFA、TTFB、H100、Consumer GPU、Artificial Analysis、Speech Arena、Provider Voice Arena、qualityElo、置信区间、Elo 榜、自建基准、benchmark 自评、指标拼接、口径拼接、Qwen3-TTS、CosyVoice、F5-TTS、Fish-Speech、Fish Audio S2 Pro、IndexTTS、Spark-TTS、Higgs Audio、Kokoro、Chatterbox、VibeVoice、XTTS、Gemini TTS、ElevenLabs、Cartesia、Inworld、MiniMax、Voxtral、StepFun StepAudio、HoppouAI、audio.cpp、GGUF、MLX、Apple Silicon、ROCm</p></blockquote>',14)])])}const h=o(e,[["render",i]]);export{q as __pageData,h as default};
